def read_report(kind,suffix):
    path=review.download("final-"+kind,PINS[kind])
    with zipfile.ZipFile(path) as archive:
        member=review.member(archive,suffix);raw=archive.read(member)
        value=json.loads(raw)
    path.unlink()
    return value,{"artifact":PINS[kind][0],"bytes":PINS[kind][1],"archiveSha256":PINS[kind][2],
        "member":member,"originalJsonSha256":review.sha(raw)}
def main():
    review.require(len(RUNS)==28 and all(r["head"]==HEAD and r["status"]=="completed" and
        r["conclusion"]=="success" and r["attempt"]==1 for r in RUNS),"Final 28 first-attempt workflows required")
    baseline,base_identity=read_report("baseline","qualification.json")
    rb,rb_identity=read_report("rb","rb-series-qualification.json")
    review.require(baseline["status"]=="PASS" and baseline["consistentExactBinary"] and baseline["ownerSourceConsistency"],"Baseline did not qualify")
    review.require(len(baseline["families"])==13 and all(r["status"]=="PASS" for r in baseline["families"].values()),"13 passing actual families required")
    review.require(all(m["sourceCommit"]==HEAD and m["sourceTree"]==TREE and m["reviewedHeadCommit"]==HEAD and
        m["releaseSha256"]==review.JAR and m["dirty"] is False for m in baseline["identities"]),"Baseline identity mismatch")
    review.require(rb["status"]=="PASS" and rb["sourceCommit"]==HEAD and rb["sourceTree"]==TREE and rb["releaseSha256"]==review.JAR,"RB collector identity mismatch")
    review.require(len(rb["units"])==9 and all(u["status"]=="PASS" and u["component_result"]=="PASS" and
        u["native_result"]=="PASS" and u["network_E2E_result"]=="PASS" for u in rb["units"]),"All nine real-layer owners required")
    units=[]
    for u in rb["units"]:
        m=u["metadata"]
        review.require(m["sourceCommit"]==HEAD and m["sourceTree"]==TREE and m["releaseSha256"]==review.JAR and
            m["dirty"] is False,"RB unit metadata mismatch")
        units.append({k:u[k] for k in ("unit","family","status","component_result","native_result","network_E2E_result",
            "ownerRun","moduleCases","nativePhases","screenshotsVerified","retainedOriginalCaptures","metadata","artifacts")})
    path=review.download("final-native",PINS["native"])
    with zipfile.ZipFile(path) as archive:
        name=review.member(archive,"fabric/build/libs/ai-villages-0.1.0.jar");data=archive.read(name)
        review.require(review.sha(data)==review.JAR,"Actual full final-head JAR bytes differ")
        binary={"member":name,"bytes":len(data),"sha256":review.sha(data),"artifact":PINS["native"][0],
            "archiveSha256":PINS["native"][2]}
    path.unlink()
    result={"schema":1,"status":"PASS","sourceHead":HEAD,"sourceTree":TREE,"sourcePR":41,
        "productionBaseline":"895304eb4b7e2379c6b82f7cda49b7ab6c9e1ebf","actualFullProductionBinary":binary,
        "workflows":RUNS,"baselineArchive":base_identity,"rbArchive":rb_identity,
        "baselineFamilies":{k:{"status":v["status"]} for k,v in baseline["families"].items()},
        "baselineIdentities":baseline["identities"],"resourceUnits":units,
        "nativePhasesVerified":sum(len(u["nativePhases"]) for u in units),
        "nativeFramesVerified":sum(u["screenshotsVerified"] for u in units),
        "retainedOriginalFrames":sum(len(u["retainedOriginalCaptures"]) for u in units),
        "rule":"This current-head qualification is distinct from the frozen primary 45-case measurement; no score pooling or minimum planning success gate."}
    review.require(result["nativePhasesVerified"]==35,"Required native phase selection changed")
    review.emit_file("evidence/rb-generalization-final-qualification.json",review.canonical(result).decode()+"\n")
    print("FINAL_QUALIFICATION_RESULT "+json.dumps({k:result[k] for k in
        ("status","sourceHead","sourceTree","actualFullProductionBinary","nativePhasesVerified","nativeFramesVerified","retainedOriginalFrames")},separators=(",",":")),flush=True)
